import Foundation
private let offset: UInt64 = 1_469_598_103_934_665_603
private let prime: UInt64 = 1_099_511_628_211
private func hash(_ seed: UInt64, _ value: UInt64) -> UInt64 { var result = seed; for index in 0..<8 { result ^= (value >> UInt64(index * 8)) & 255; result &*= prime }; return result }
@main struct SM64SnowMoundSmoke { static func main() { let slide = SM64SnowMoundBehavior.updateSliding(.init(action: 0, timer: 118, position: .init(x: 0, y: 10, z: 4), homeZ: 4)); let fall = SM64SnowMoundBehavior.updateSliding(.init(action: 1, timer: 51, position: .init(x: 0, y: 10, z: 4), homeZ: 4)); let spawn = SM64SnowMoundBehavior.updateSpawner(.init(timer: 256, distanceToMario: 100, marioY: 0, positionY: 0)); precondition(slide.action == 1 && slide.position.x == -40 && slide.playSinkSound); precondition(fall.shouldDelete && fall.position.z == 2); precondition(spawn.timer == 0 && spawn.spawnChild && spawn.childScale == 2); var fingerprint = offset; for value in [UInt64(bitPattern: Int64(slide.action)), UInt64(slide.position.x.bitPattern), UInt64(bitPattern: Int64(fall.timer)), spawn.spawnChild ? 1 : 0, UInt64(spawn.childScale.bitPattern)] { fingerprint = hash(fingerprint, value) }; print(String(format: "snowMoundFingerprint=0x%016llx", fingerprint)); print("SM64 Modern snow mound smoke passed") } }
